# Emits internal/audio/prompts_gen.go from the Rails provider constants, so the
# steering prompts (which are part of every clip key) are byte-identical.
#   bin/rails runner tools/gen/audio_prompts.rb | sed -n "/^\/\/ Code generated/,$p" > internal/audio/prompts_gen.go
def go_map(name, hash)
  body = hash.map { |k, v| "\t#{k.to_json}: #{v.to_json}," }.join("\n")
  "var #{name} = map[string]string{\n#{body}\n}\n"
end

puts "// Code generated by tools/gen/audio_prompts.rb from the Rails providers. DO NOT EDIT.\n\npackage audio\n\n"
puts go_map("openAIInstructions", Audio::Providers::OpenAi::DEFAULT_INSTRUCTIONS_BY_LANGUAGE)
puts
puts go_map("googleInstructions", Audio::Providers::Google::DEFAULT_INSTRUCTIONS_BY_LANGUAGE)
puts
puts go_map("googleShortInstructions", Audio::Providers::Google::SHORT_INPUT_INSTRUCTIONS_BY_LANGUAGE)
puts
puts "const elevenLabsModelID = #{ElevenlabsAudioService::MODEL_ID.to_json}"
